pub fn get(id: &str) -> Option<&'static Mesh> {
    match id {
        "claude" => Some(&CLAUDE),
        "codex" => Some(&CODEX),
        "gemini" => Some(&GEMINI),
        "opencode" => Some(&OPENCODE),
        "pi" => Some(&PI),
        "qwen" => Some(&QWEN),
        "aider" => Some(&AIDER),
        "goose" => Some(&GOOSE),
        "zed" => Some(&ZED),
        "vscode" => Some(&VSCODE),
        "cursor" => Some(&CURSOR),
        "amp" => Some(&AMP),
        "continue" => Some(&CONTINUE),
        "cline" => Some(&CLINE),
        "roo" => Some(&ROO),
        "kilo" => Some(&KILO),
        _ => None,
    }
}
